7	+// Minimal, deterministic stand-in for the running game.
8	+//
9	+// The real game exposes its state as globals (`player`, `Tickspeed`, `format`,
10	+// ...) and drives every component by calling its `update()` once per frame.
11	+// These helpers reproduce just enough of that so a component can be mounted and
12	+// asked what it renders for a given game state. They say nothing about how any
13	+// component is implemented.
14	+import Vue from "vue";
15	+
16	+const d = v => new Decimal(v);
17	+
18	+const num = v => (v && typeof v.toNumber === "function" ? v.toNumber() : Number(v));
19	+
20	+// Number formatters mirroring the shapes the game's own helpers produce, so
21	+// rendered text is readable and stable.
22	+const format = (v, places = 0, placesUnder1000 = 0) => num(v).toFixed(Math.max(places, placesUnder1000));
23	+const formatInt = v => String(Math.round(num(v)));
24	+const formatFloat = (v, places = 0) => num(v).toFixed(places);
25	+const formatX = (v, places = 0, placesUnder1000 = 0) => `×${format(v, places, placesUnder1000)}`;
26	+const formatPercents = (v, places = 0) => `${(num(v) * 100).toFixed(places)}%`;
27	+const formatPow = (v, places = 0, placesUnder1000 = 0) => `^${format(v, places, placesUnder1000)}`;
28	+const pluralize = (word, amount, plural) => (num(amount) === 1 ? word : plural ?? `${word}s`);
29	+const quantify = (word, amount, places = 0) => `${format(amount, places)} ${pluralize(word, amount)}`;
30	+const quantifyInt = (word, amount) => `${formatInt(amount)} ${pluralize(word, amount)}`;
31	+
32	+// Distinctive readings so assertions can tell "the component was fed real game
33	+// state" apart from "the component rendered its zeroed defaults".
34	+export const TICKSPEED_PER_SECOND = 7;
35	+export const TICKSPEED_MULT_PER_UPGRADE = 8;
36	+
37	+/**
38	+ * Publish a whole game state as globals.
39	+ *
40	+ * @param {object} opts
41	+ * @param {boolean} opts.newUI            true = Modern UI theme, false = Classic
42	+ * @param {boolean} opts.realityUnlocked  has the player unlocked Reality yet
43	+ * @param {boolean} opts.tickspeedUnlocked has Tickspeed become relevant yet
44	+ */
