174	+    // scope, which is not always the same object as globalThis.
175	+    if (typeof window !== "undefined") window[key] = value;
176	+    // Vue 2 templates resolve bare identifiers against the component instance,
177	+    // so the same names have to be reachable from the prototype chain too.
178	+    Vue.prototype[key] = value;
179	+  }
180	+
181	+  return globals;
182	+}
183	+
184	+/** Publish (or replace) a single game global everywhere a component can see it. */
185	+export function setGameGlobal(name, value) {
186	+  globalThis[name] = value;
187	+  if (typeof window !== "undefined") window[name] = value;
188	+  Vue.prototype[name] = value;
189	+  return value;
190	+}
