192	+// A handful of prototype helpers the game installs at boot and some components
193	+// reach for while rendering.
194	+export function installPrototypeHelpers() {
195	+  if (!Math.clampMax) Math.clampMax = (value, max) => Math.min(value, max);
196	+  if (!Math.clampMin) Math.clampMin = (value, min) => Math.max(value, min);
197	+  if (!Math.clamp) Math.clamp = (value, min, max) => Math.min(Math.max(value, min), max);
198	+  if (!Array.prototype.sum) {
199	+    // eslint-disable-next-line no-extend-native
200	+    Object.defineProperty(Array.prototype, "sum", {
201	+      value() { return this.reduce((a, b) => a + b, 0); },
202	+      enumerable: false,
203	+    });
204	+  }
205	+  if (!Decimal.prototype.pLog10) {
206	+    Decimal.prototype.pLog10 = function pLog10() { return Math.max(this.log10(), 0); };
207	+  }
208	+}
