213	+ * Peripheral components that the stubbed state cannot fully satisfy are allowed
214	+ * to bail out — anything the test actually asserts on has to render anyway.
215	+ */
216	+export async function runGameLoop(wrapper, frames = 2) {
217	+  for (let frame = 0; frame < frames; frame++) {
218	+    const visit = vm => {
